# -*- coding: utf-8 -*-
"""
config.py의 BRAND 컬러를 이용해 Streamlit 기본 위젯 위에 커스텀 CSS를 입히는 공용 모듈.
apply_app.py, admin_app.py 양쪽에서 똑같이 불러다 씁니다.

주의: 모든 동적 HTML 조각은 '한 줄' 문자열로 만든다. (여러 줄로 예쁘게 들여써서 만들면
마크다운 파서가 일부 줄을 코드블록/별도 문단으로 잘못 해석해서 빈 박스가 생기는 등
렌더링이 깨지는 문제가 있었음. 그래서 항상 줄바꿈 없이 이어붙인 뒤 한 번에 출력한다.)
"""
import base64
import io
import re
import pandas as pd
import streamlit as st
import streamlit.components.v1 as components
import config

MASCOT_B64 = ""


def pdf_view_button(pdf_b64: str, label: str = "PDF 새 탭에서 보기", key: str = "pdf_view_btn"):
    """화면 안(iframe)에 PDF를 끼워넣는 방식은 Streamlit 컴포넌트가 샌드박스 안에 있어서
    브라우저/환경에 따라 빈 화면만 뜨는 문제가 있었다. 그래서 버튼을 누르면 브라우저의 새 탭
    (최상위 창)에서 PDF를 여는 방식으로 한다 — 다운로드가 아니라 브라우저 내장 뷰어로 바로 보임.
    한 화면에 여러 번 쓸 수 있으므로 key로 버튼 id를 구분한다."""
    b = config.BRAND
    components.html(
        f"<button id='{key}' style='width:100%;padding:11px 16px;border-radius:8px;"
        f"border:1px solid {b['primary']};background:{b['primary']};color:#fff;"
        "font-weight:600;font-size:15px;cursor:pointer;'>" + label + "</button>"
        "<script>"
        f"document.getElementById('{key}').onclick = function() {{"
        f"const b64 = '{pdf_b64}';"
        "const byteChars = atob(b64);"
        "const byteNumbers = new Array(byteChars.length);"
        "for (let i = 0; i < byteChars.length; i++) { byteNumbers[i] = byteChars.charCodeAt(i); }"
        "const byteArray = new Uint8Array(byteNumbers);"
        "const blob = new Blob([byteArray], {type: 'application/pdf'});"
        "const url = URL.createObjectURL(blob);"
        "window.open(url, '_blank');"
        "};"
        "</script>",
        height=54,
    )


def mascot_icon():
    """st.set_page_config(page_icon=...)에 쓸 마스코트 이미지 (브라우저 탭 아이콘용)."""
    from PIL import Image
    return Image.open(io.BytesIO(base64.b64decode(MASCOT_B64)))


def scroll_to_top():
    """홈↔지원하기 등 화면을 전환할 때, 이전 화면에서 내려가 있던 스크롤 위치가 그대로 남아
    새 화면이 중간부터 보이는 문제가 있어서, 화면이 바뀔 때 맨 위로 강제로 스크롤한다.
    화면 전환 직후엔 아래쪽 내용이 아직 다 그려지지 않은 상태라 스크롤 명령이 씹히는 경우가
    있어서, 한 번만 실행하지 않고 짧은 시간차를 두고 여러 번 반복 실행해 확실히 맨 위로 보낸다."""
    components.html(
        "<script>"
        "function goTop(){const d=window.parent.document;"
        "const m=d.querySelector('[data-testid=\"stMain\"]')||d.querySelector('section.main')||d.scrollingElement;"
        "if(m){m.scrollTo({top:0,behavior:'instant'});}"
        "window.parent.scrollTo(0,0);}"
        "goTop();"
        "[50,150,300,600].forEach(t=>setTimeout(goTop,t));"
        "</script>",
        height=0,
    )


def _render(html: str):
    """HTML을 그대로 렌더링 (줄바꿈이 섞이지 않도록 호출부에서 항상 한 줄로 만들어서 넘길 것)."""
    st.markdown(html, unsafe_allow_html=True)


def inject_css(css: str):
    """apply_app.py/admin_app.py에서 특정 위젯 하나에만 CSS를 살짝 덧입히고 싶을 때 쓰는 공개 헬퍼."""
    _render(f"<style>{css}</style>")


def submission_success_card(contact_email: str):
    """제출 완료 화면. 기본 st.success(초록)+st.info(파랑) 조합 대신, 사이트 브랜드 컬러에
    맞춘 카드 하나로 통일해서 화면이 여러 색이 뒤섞여 조잡해 보이지 않게 한다."""
    b = config.BRAND
    _render(
        '<div style="text-align:center;padding:10px 0 6px;">'
        '<div style="font-size:34px;line-height:1;">✅</div>'
        f'<div style="font-size:19px;font-weight:700;color:{b["primary_dark"]};margin:10px 0 6px;">'
        '지원이 정상적으로 완료되었습니다</div>'
        f'<div style="font-size:13px;color:#888;">문의사항은 '
        f'<a href="mailto:{contact_email}" style="color:{b["primary"]};font-weight:600;text-decoration:none;">'
        f'{contact_email}</a> 로 연락 부탁드립니다.</div>'
        '</div>'
    )


def program_badge(round_key: str):
    """지원서 작성 화면 맨 위, 큰 입력칸 대신 작은 배지로 지금 몇 회차 접수 중인지 보여준다.
    (필수 입력칸처럼 보여서 첫 질문과 헷갈리지 않게, 그러면서도 눈에 잘 띄게 진한 글씨로)"""
    b = config.BRAND
    _render(
        f'<div style="display:inline-block;background:{b["page_bg"]};border:1px solid {b["primary_light"]};'
        f'border-radius:999px;padding:5px 14px;margin-bottom:14px;font-size:12px;font-weight:700;'
        f'color:{b["primary_dark"]};">지원 프로그램 · {round_key}</div>'
    )


def inline_error(text: str):
    """st.error()는 글자가 커서, 입력폼 실시간 검증용으로 작은 빨간 글씨 경고를 대신 쓴다."""
    _render(f'<div style="color:#D33;font-size:12px;margin:-8px 0 8px 2px;">⚠ {text}</div>')


