def clickable_bar_chart(title: str, counts: dict, state_key: str):
    """교수님별 인원수를 표 + 진행바(ProgressColumn)로 보여주고, '인원' 숫자가 있는 행을 누르면
    그 교수님이 선택되게 한다. 흰 카드 안에 넣어서 지원자 사이트(apply_box)와 톤을 맞춘다.
    선택된 값은 st.session_state[state_key]에 저장한다 (호출부에서 읽어서 목록을 보여줄 것)."""
    b = config.BRAND
    box_key = f"cbc_box_{state_key}"
    with st.container(key=box_key):
        st.markdown(f"**{title}**")
        if not counts:
            st.caption("데이터가 없어요.")
        else:
            items = sorted(counts.items(), key=lambda kv: -kv[1])
            cdf = pd.DataFrame({"교수님": [k for k, _ in items], "인원": [v for _, v in items]})
            max_v = int(cdf["인원"].max())
            event = st.dataframe(
                cdf, use_container_width=True, hide_index=True,
                on_select="rerun", selection_mode="single-row", key=f"prof_df_{state_key}",
                column_config={"인원": st.column_config.ProgressColumn("인원", min_value=0, max_value=max_v, format="%d명")},
            )
            rows = (event or {}).get("selection", {}).get("rows", [])
            st.session_state[state_key] = cdf.iloc[rows[0]]["교수님"] if rows else None
    _render(
        "<style>"
        f'.st-key-{box_key} {{ background:#fff;border:1px solid {b["primary_light"]};'
        "border-radius:10px;padding:16px 18px; }"
        "</style>"
    )


def prof_summary_table(counts1: dict, counts2: dict, state_key: str, all_profs_list: list = None):
    """표(st.dataframe)에 교수님별 1지망/2지망 인원을 숫자로만 보여준다 (진행바까지는
    과했다는 판단으로 뺐다). 체크박스는 표의 행 선택 기능에 기본으로 붙는 것이라 이 컴포넌트를
    쓰는 한 뺄 수 없다 — 완전히 없애려면 커스텀 버튼으로 가야 하는데, 그건 공간을 더 쓴다는
    트레이드오프가 있어 이번엔 표 쪽으로 정리했다. 행을 누르면 그 교수님을 선택 상태로 저장한다.
    all_profs_list를 주면, 아직 지원자가 0명인 교수님도 빠짐없이 목록에 나온다 (안 주면
    지원자가 1명이라도 있는 교수님만 나온다)."""
    b = config.BRAND
    base = all_profs_list if all_profs_list is not None else list(set(counts1) | set(counts2))
    all_profs = sorted(base)
    if not all_profs:
        st.caption("데이터가 없어요.")
        return
    box_key = f"pst_box_{state_key}"
    with st.container(key=box_key):
        tdf = pd.DataFrame({
            "교수님": all_profs,
            "1지망": [int(counts1.get(p, 0)) for p in all_profs],
            "2지망": [int(counts2.get(p, 0)) for p in all_profs],
        })
        # 기본 높이로 두면 교수님이 많을 때 표 안에서 또 스크롤이 생기므로,
        # 행 수에 맞춰 높이를 계산해서 전부 한 번에 보이게 한다.
        _tbl_height = 38 + 35 * len(all_profs) + 3
        event = st.dataframe(
            tdf, use_container_width=True, hide_index=True, height=_tbl_height,
            on_select="rerun", selection_mode="single-row", key=f"prof_summary_{state_key}",
        )
        rows = (event or {}).get("selection", {}).get("rows", [])
        st.session_state[state_key] = tdf.iloc[rows[0]]["교수님"] if rows else None
    _render(
        "<style>"
        f'.st-key-{box_key} {{ background:#fff;border:1px solid {b["primary_light"]};'
        f'border-left:4px solid {b["primary"]};border-radius:10px;padding:14px 16px; }}'
        "</style>"
    )


def bar_list(title: str, counts: dict):
    """교수님별 지원자 수 같은 걸 가로 막대그래프로 보여준다. counts: {라벨: 숫자}"""
    b = config.BRAND
    if not counts:
        _render(f'<div style="font-size:13px;color:#999;">{title} - 데이터 없음</div>')
        return
    max_v = max(counts.values()) or 1
    rows = "".join(
        '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
        f'<div style="width:70px;font-size:12px;color:#333;flex-shrink:0;text-align:right;">{label}</div>'
        f'<div style="flex:1;background:#F1E6EE;border-radius:4px;overflow:hidden;height:16px;">'
        f'<div style="width:{max(6, int(v / max_v * 100))}%;background:{b["primary"]};height:100%;"></div></div>'
        f'<div style="width:24px;font-size:12px;color:#333;flex-shrink:0;">{v}</div>'
        '</div>'
        for label, v in counts.items()
    )
    html = (
        f'<div style="font-size:13px;font-weight:700;color:{b["primary_dark"]};margin-bottom:10px;">{title}</div>'
        f'<div style="background:#fff;border:1px solid #E7D6E2;border-radius:8px;padding:14px 16px;">{rows}</div>'
    )
    _render(html)


def summary_cards(items):
    """전체 지원자 / 환산불가 / 중복 지원 의심 같은 요약 카드. items: [(label, value, note), ...]
    클릭용이 아니라 순수 표시용 (클릭 필터는 버튼으로 별도 처리)."""
    b = config.BRAND
    cols = st.columns(len(items))
    for col, (label, value, note) in zip(cols, items):
        with col:
            _render(
                '<div style="background:#fff;border:1px solid '
                f'{b["primary_light"]};border-radius:8px;padding:14px 16px;">'
                f'<div style="font-size:12px;color:#888;margin-bottom:4px;">{label}</div>'
                f'<div style="font-size:22px;font-weight:700;color:{b["primary_dark"]};">{value}</div>'
                f'<div style="font-size:11px;color:#999;margin-top:2px;">{note}</div></div>'
            )


def quick_filter_card(label: str, value: str, note: str, key: str, active: bool) -> bool:
    """전체보기/환산불가만보기 같은 요약 카드 자체를 버튼으로 만들어, 숫자나 카드 아무 곳이나
    누르면 바로 필터가 적용되게 한다 (카드 따로 + 버튼 따로였던 것을 하나로 합침).
    st.button의 라벨에 '\\n\\n'을 넣으면 문단이 두 개(<p> 두 개)로 나뉘어 렌더링되는 점을
    이용해서, 첫 <p>는 큰 숫자로 / 나머지는 작은 라벨로 CSS를 나눠 입힌다."""
    b = config.BRAND
    label_text = f"{value}\n\n{label}" + (f"\n\n{note}" if note else "")
    with st.container(key=f"qfc_{key}"):
        clicked = st.button(
            label_text,
            key=f"qfc_btn_{key}", use_container_width=True,
            type=("primary" if active else "secondary"),
        )
    _render(
        "<style>"
        'div[class*="st-key-qfc_"] button {'
        "height:auto !important; min-height:auto !important; text-align:left !important; "
        "padding:14px 16px !important; border-radius:8px !important; white-space:normal !important; }"
        'div[class*="st-key-qfc_"] button[kind="secondary"] {'
        f'background:#fff !important; border:1px solid {b["primary_light"]} !important; }}'
        'div[class*="st-key-qfc_"] button div[data-testid="stMarkdownContainer"] > p:nth-of-type(1) {'
        f'font-size:20px !important; font-weight:700 !important; margin:0 0 2px 0 !important; color:{b["primary_dark"]} !important; }}'
        'div[class*="st-key-qfc_"] button[kind="secondary"] div[data-testid="stMarkdownContainer"] > p:nth-of-type(1) {'
        "color:#222 !important; }"
        'div[class*="st-key-qfc_"] button div[data-testid="stMarkdownContainer"] > p:nth-of-type(2) {'
        "font-size:11px !important; font-weight:600 !important; margin:0 !important; color:#666 !important; }"
        'div[class*="st-key-qfc_"] button[kind="primary"] div[data-testid="stMarkdownContainer"] > p:nth-of-type(2) {'
        "color:#fff !important; }"
        'div[class*="st-key-qfc_"] button div[data-testid="stMarkdownContainer"] > p:nth-of-type(3) {'
        "font-size:11px !important; margin:2px 0 0 0 !important; color:#999 !important; }"
        'div[class*="st-key-qfc_"] button[kind="primary"] div[data-testid="stMarkdownContainer"] > p:nth-of-type(3) {'
        "color:#F1DFEC !important; }"
        "</style>"
    )
    return clicked


